export default "import { VuiSteps, Steps } from \"../../../lib\";\nimport { Subsection } from \"../../components/Subsection\";\n\nexport const StepSizes = () => {\n  const basicSteps: Steps = [\n    {\n      title: \"Completed step\",\n      status: \"complete\"\n    },\n    {\n      title: \"Selected step\",\n      status: \"current\"\n    },\n    {\n      title: \"Incomplete step which will wrap to the next line\",\n      status: \"incomplete\"\n    }\n  ];\n\n  const sizes = [\n    {\n      size: \"xs\" as const,\n      description: \"Size xs\"\n    },\n    {\n      size: \"s\" as const,\n      description: \"Size s\"\n    },\n    {\n      size: \"m\" as const,\n      description: \"Size m\"\n    }\n  ];\n\n  return (\n    <>\n      {sizes.map(({ size, description }) => (\n        <Subsection key={size} title={description}>\n          <VuiSteps steps={basicSteps} size={size} />\n        </Subsection>\n      ))}\n    </>\n  );\n};\n";