export default "import { useState } from \"react\";\nimport {\n  VuiAccordion,\n  VuiText,\n  VuiSelect,\n  VuiSpacer,\n  VuiCheckbox,\n  VuiFlexContainer,\n  VuiFlexItem,\n  VuiFormGroup,\n  VuiPopover,\n  VuiOptionsList,\n  VuiIcon,\n  VuiIconButton\n} from \"../../../lib\";\nimport { BiDotsHorizontalRounded } from \"react-icons/bi\";\n\nconst headerSizeOptions = [\n  { text: \"Extra small (xs)\", value: \"xs\" },\n  { text: \"Small (s)\", value: \"s\" },\n  { text: \"Medium (m)\", value: \"m\" },\n  { text: \"Large (l)\", value: \"l\" }\n];\n\nconst paddingOptions = [\n  { text: \"Medium (m)\", value: \"m\" },\n  { text: \"None\", value: \"none\" }\n];\n\nconst appendOptions = [\n  { value: \"edit\", label: \"Edit\" },\n  { value: \"duplicate\", label: \"Duplicate\" },\n  { value: \"delete\", label: \"Delete\" }\n];\n\nexport const Accordion = () => {\n  const [isOpen, setIsOpen] = useState(false);\n  const [headerSize, setHeaderSize] = useState<\"xs\" | \"s\" | \"m\" | \"l\">(\"s\");\n  const [padding, setPadding] = useState<\"m\" | \"none\">(\"m\");\n  const [bodyPadding, setBodyPadding] = useState<\"m\" | \"none\">(\"m\");\n  const [frame, setFrame] = useState(true);\n  const [showAppend, setShowAppend] = useState(false);\n  const [isPopoverOpen, setIsPopoverOpen] = useState(false);\n\n  return (\n    <>\n      <VuiFlexContainer spacing=\"m\" alignItems=\"start\">\n        <VuiFlexItem>\n          <VuiFormGroup label=\"Header size\" labelFor=\"headerSizeSelect\">\n            <VuiSelect\n              id=\"headerSizeSelect\"\n              options={headerSizeOptions}\n              value={headerSize}\n              onChange={(e) => setHeaderSize(e.target.value as \"xs\" | \"s\" | \"m\" | \"l\")}\n            />\n          </VuiFormGroup>\n        </VuiFlexItem>\n\n        <VuiFlexItem>\n          <VuiFormGroup label=\"Padding\" labelFor=\"paddingSelect\">\n            <VuiSelect\n              id=\"paddingSelect\"\n              options={paddingOptions}\n              value={padding}\n              onChange={(e) => setPadding(e.target.value as \"m\" | \"none\")}\n            />\n          </VuiFormGroup>\n        </VuiFlexItem>\n\n        <VuiFlexItem>\n          <VuiFormGroup label=\"Body padding\" labelFor=\"bodyPaddingSelect\">\n            <VuiSelect\n              id=\"bodyPaddingSelect\"\n              options={paddingOptions}\n              value={bodyPadding}\n              onChange={(e) => setBodyPadding(e.target.value as \"m\" | \"none\")}\n            />\n          </VuiFormGroup>\n        </VuiFlexItem>\n\n        <VuiFlexItem>\n          <VuiCheckbox label=\"Frame\" checked={frame} onChange={(e) => setFrame(e.target.checked)} />\n        </VuiFlexItem>\n\n        <VuiFlexItem>\n          <VuiCheckbox label=\"Append\" checked={showAppend} onChange={(e) => setShowAppend(e.target.checked)} />\n        </VuiFlexItem>\n      </VuiFlexContainer>\n\n      <VuiSpacer size=\"m\" />\n\n      <VuiAccordion\n        header=\"Accordion header\"\n        isOpen={isOpen}\n        setIsOpen={setIsOpen}\n        headerSize={headerSize}\n        padding={padding}\n        bodyPadding={bodyPadding}\n        frame={frame}\n        append={\n          showAppend ? (\n            <VuiPopover\n              isOpen={isPopoverOpen}\n              setIsOpen={setIsPopoverOpen}\n              button={\n                <VuiIconButton\n                  aria-label=\"More options\"\n                  icon={\n                    <VuiIcon>\n                      <BiDotsHorizontalRounded />\n                    </VuiIcon>\n                  }\n                  color=\"neutral\"\n                />\n              }\n            >\n              <VuiOptionsList onSelectOption={() => setIsPopoverOpen(false)} options={appendOptions} />\n            </VuiPopover>\n          ) : undefined\n        }\n      >\n        <VuiText>\n          <p>Accordion content goes here.</p>\n        </VuiText>\n      </VuiAccordion>\n    </>\n  );\n};\n";