export default "import { BiPlanet } from \"react-icons/bi\";\nimport {\n  VuiButtonPrimary,\n  VuiCard,\n  VuiFlexContainer,\n  VuiFlexItem,\n  VuiIcon,\n  VuiSelect,\n  VuiSpacer,\n  VuiText,\n  VuiTitle\n} from \"../../../lib\";\nimport { useState } from \"react\";\n\nconst paddingOptions = [\n  { text: \"Extra extra small\", value: \"xxs\" },\n  { text: \"Extra small\", value: \"xs\" },\n  { text: \"Small\", value: \"s\" },\n  { text: \"Medium\", value: \"m\" },\n  { text: \"Large\", value: \"l\" }\n];\n\nexport const Expandable = () => {\n  const [padding, setPadding] = useState<\"xxs\" | \"xs\" | \"s\" | \"m\" | \"l\">(\"xs\");\n  const [isExpanded1, setIsExpanded1] = useState(false);\n  const [isExpanded2, setIsExpanded2] = useState(true);\n  const [isExpanded3, setIsExpanded3] = useState(false);\n\n  return (\n    <>\n      <VuiText>\n        <p>Cards can act as expandable containers with controlled expand/collapse functionality.</p>\n      </VuiText>\n\n      <VuiSpacer size=\"s\" />\n\n      <VuiSelect\n        id=\"paddingOptions\"\n        options={paddingOptions}\n        value={padding}\n        onChange={(event) => setPadding(event.target.value as \"xxs\" | \"xs\" | \"s\" | \"m\" | \"l\")}\n      />\n\n      <VuiSpacer size=\"m\" />\n\n      <VuiFlexContainer direction=\"column\" spacing=\"m\">\n        <VuiFlexItem>\n          <VuiCard\n            padding={padding}\n            isExpanded={isExpanded1}\n            onToggleExpansion={() => setIsExpanded1(!isExpanded1)}\n            header={\n              <VuiFlexContainer alignItems=\"center\" spacing=\"s\">\n                <VuiFlexItem grow={false}>\n                  <VuiIcon color=\"neutral\" size=\"s\">\n                    <BiPlanet />\n                  </VuiIcon>\n                </VuiFlexItem>\n                <VuiFlexItem grow={1}>\n                  <VuiTitle size=\"xs\">\n                    <h4>Explore Alpha Centauri</h4>\n                  </VuiTitle>\n                </VuiFlexItem>\n              </VuiFlexContainer>\n            }\n            body={\n              <>\n                <VuiText>\n                  <p>\n                    Alpha Centauri is the closest star system and closest planetary system to Earth's Solar System at\n                    4.37 light-years from the Sun. The name is Latinized from α Centauri, and abbreviated Alpha Cen or α\n                    Cen.\n                  </p>\n                </VuiText>\n                <VuiSpacer size=\"s\" />\n                <VuiText>\n                  <p>\n                    It is a triple star system, consisting of the three stars: α Centauri A (officially Rigil\n                    Kentaurus), α Centauri B (officially Toliman), and the closest star α Centauri C (officially Proxima\n                    Centauri).\n                  </p>\n                </VuiText>\n                <VuiSpacer size=\"m\" />\n                <VuiButtonPrimary color=\"success\">Learn More</VuiButtonPrimary>\n              </>\n            }\n          />\n        </VuiFlexItem>\n\n        <VuiFlexItem>\n          <VuiCard\n            padding={padding}\n            isExpanded={isExpanded2}\n            onToggleExpansion={() => setIsExpanded2(!isExpanded2)}\n            header={\n              <VuiFlexContainer alignItems=\"center\" spacing=\"s\">\n                <VuiFlexItem grow={false}>\n                  <VuiIcon color=\"neutral\" size=\"m\">\n                    <BiPlanet />\n                  </VuiIcon>\n                </VuiFlexItem>\n                <VuiFlexItem grow={1}>\n                  <VuiTitle size=\"s\">\n                    <h4>Journey to Proxima b (Initially Expanded)</h4>\n                  </VuiTitle>\n                </VuiFlexItem>\n              </VuiFlexContainer>\n            }\n            body={\n              <>\n                <VuiText>\n                  <p>\n                    Proxima Centauri b is a terrestrial exoplanet orbiting in the habitable zone of the red dwarf star\n                    Proxima Centauri, the closest star to the Sun and part of the Alpha Centauri system.\n                  </p>\n                </VuiText>\n                <VuiSpacer size=\"s\" />\n                <VuiText>\n                  <p>\n                    It is located approximately 4.2 light-years from Earth in the constellation Centaurus, making it the\n                    closest known exoplanet to the Solar System.\n                  </p>\n                </VuiText>\n              </>\n            }\n          />\n        </VuiFlexItem>\n\n        <VuiFlexItem>\n          <VuiCard\n            padding={padding}\n            isExpanded={isExpanded3}\n            onToggleExpansion={() => setIsExpanded3(!isExpanded3)}\n            header={\n              <VuiTitle size=\"s\">\n                <h4>Simple Text Header</h4>\n              </VuiTitle>\n            }\n            body={\n              <VuiText>\n                <p>\n                  This expandable card demonstrates a simpler header without icons. The expandable functionality works\n                  with any content you provide as the header and body props. The parent component maintains full control\n                  over the expanded/collapsed state through the isExpanded and onToggleExpansion props.\n                </p>\n              </VuiText>\n            }\n          />\n        </VuiFlexItem>\n      </VuiFlexContainer>\n    </>\n  );\n};\n";