export default "import { useState } from \"react\";\nimport { VuiSelect, VuiSpacer } from \"../../../lib\";\n\nconst options = [\n  { text: \"Johann Baptist Christophorus Apollinaris von Albertini\", value: \"albertini\" },\n  { text: \"David Brin\", value: \"brin\" },\n  { text: \"Cormac McCarthy\", value: \"mccarthy\" },\n  { text: \"Bret Easton Ellis\", value: \"ellis\" }\n];\n\nexport const Select = () => {\n  const [value, setValue] = useState(\"albertini\");\n\n  return (\n    <>\n      <VuiSelect\n        id=\"optionsList1\"\n        size=\"s\"\n        options={options}\n        value={value}\n        onChange={(event) => setValue(event.target.value)}\n      />\n\n      <VuiSpacer size=\"m\" />\n\n      <VuiSelect\n        id=\"optionsList2\"\n        size=\"m\"\n        options={options}\n        value={value}\n        onChange={(event) => setValue(event.target.value)}\n      />\n\n      <VuiSpacer size=\"m\" />\n\n      <VuiSelect\n        id=\"optionsList3\"\n        size=\"l\"\n        options={options}\n        value={value}\n        onChange={(event) => setValue(event.target.value)}\n      />\n    </>\n  );\n};\n";